import { YorkieEventController } from './yorkie-event.controller';
import { DocumentService } from './document.service';

describe('YorkieEventController', () => {
  let touchUpdatedAt: jest.Mock;
  let controller: YorkieEventController;

  beforeEach(() => {
    touchUpdatedAt = jest.fn().mockResolvedValue(1);
    controller = new YorkieEventController({
      touchUpdatedAt,
    } as unknown as DocumentService);
  });

  it('advances updatedAt to the event issue time on DocumentRootChanged', async () => {
    await controller.handleEvent({
      type: 'DocumentRootChanged',
      attributes: { key: 'slides-abc', issuedAt: '2026-07-10T06:03:13.331Z' },
    });
    expect(touchUpdatedAt).toHaveBeenCalledWith(
      'abc',
      new Date('2026-07-10T06:03:13.331Z'),
    );
  });

  it('ignores event types other than DocumentRootChanged', async () => {
    await controller.handleEvent({
      type: 'DocumentWatched',
      attributes: { key: 'slides-abc', issuedAt: '2026-07-10T06:03:13.331Z' },
    });
    expect(touchUpdatedAt).not.toHaveBeenCalled();
  });

  it('ignores keys with an unrecognized prefix', async () => {
    await controller.handleEvent({
      type: 'DocumentRootChanged',
      attributes: { key: 'bogus-abc', issuedAt: '2026-07-10T06:03:13.331Z' },
    });
    expect(touchUpdatedAt).not.toHaveBeenCalled();
  });

  it('clamps a future-skewed issuedAt to now() so it cannot pin updatedAt ahead', async () => {
    const before = Date.now();
    await controller.handleEvent({
      type: 'DocumentRootChanged',
      attributes: { key: 'sheet-xyz', issuedAt: '2999-01-01T00:00:00.000Z' },
    });
    const [, at] = touchUpdatedAt.mock.calls[0] as [string, Date];
    // Stored time is now(), not the year-2999 value.
    expect(at.getTime()).toBeGreaterThanOrEqual(before);
    expect(at.getTime()).toBeLessThan(Date.parse('2999-01-01T00:00:00.000Z'));
  });

  it('falls back to now() when issuedAt is missing or unparseable', async () => {
    const before = Date.now();
    await controller.handleEvent({
      type: 'DocumentRootChanged',
      attributes: { key: 'sheet-xyz' },
    });
    expect(touchUpdatedAt).toHaveBeenCalledTimes(1);
    const [id, at] = touchUpdatedAt.mock.calls[0] as [string, Date];
    expect(id).toBe('xyz');
    expect(at.getTime()).toBeGreaterThanOrEqual(before);
  });

  it('always answers ok so Yorkie does not retry', async () => {
    expect(await controller.handleEvent({ type: 'DocumentRootChanged' })).toEqual(
      { ok: true },
    );
  });
});

import {
  ServiceUnavailableException,
  UnauthorizedException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { ExecutionContext } from '@nestjs/common';
import { createHmac } from 'crypto';
import { YorkieSignatureGuard } from './yorkie-signature.guard';

const SECRET = 'test-secret-key';

function makeGuard(secret?: string): YorkieSignatureGuard {
  const config = {
    get: (key: string) =>
      key === 'YORKIE_SECRET_KEY' ? secret : undefined,
  } as unknown as ConfigService;
  return new YorkieSignatureGuard(config);
}

function contextFor(
  rawBody: Buffer | undefined,
  signature: string | undefined,
): ExecutionContext {
  const req = {
    rawBody,
    header: (name: string) =>
      name.toLowerCase() === 'x-signature-256' ? signature : undefined,
  };
  return {
    switchToHttp: () => ({ getRequest: () => req }),
  } as unknown as ExecutionContext;
}

function sign(body: Buffer, secret: string): string {
  return `sha256=${createHmac('sha256', secret).update(body).digest('hex')}`;
}

describe('YorkieSignatureGuard', () => {
  const body = Buffer.from(
    JSON.stringify({
      type: 'DocumentRootChanged',
      attributes: { key: 'sheet-1', issuedAt: '2026-07-10T00:00:00.000Z' },
    }),
  );

  it('accepts a correctly signed request', () => {
    const guard = makeGuard(SECRET);
    expect(guard.canActivate(contextFor(body, sign(body, SECRET)))).toBe(true);
  });

  it('rejects a signature computed with the wrong key', () => {
    const guard = makeGuard(SECRET);
    expect(() =>
      guard.canActivate(contextFor(body, sign(body, 'wrong-key'))),
    ).toThrow(UnauthorizedException);
  });

  it('rejects when the body was tampered with after signing', () => {
    const guard = makeGuard(SECRET);
    const sig = sign(body, SECRET);
    const tampered = Buffer.from(body.toString().replace('sheet-1', 'sheet-2'));
    expect(() => guard.canActivate(contextFor(tampered, sig))).toThrow(
      UnauthorizedException,
    );
  });

  it('rejects a missing signature header', () => {
    const guard = makeGuard(SECRET);
    expect(() => guard.canActivate(contextFor(body, undefined))).toThrow(
      UnauthorizedException,
    );
  });

  it('rejects when the raw body was not captured', () => {
    const guard = makeGuard(SECRET);
    expect(() =>
      guard.canActivate(contextFor(undefined, sign(body, SECRET))),
    ).toThrow(UnauthorizedException);
  });

  it('refuses to authenticate when no secret is configured', () => {
    const guard = makeGuard(undefined);
    expect(() =>
      guard.canActivate(contextFor(body, sign(body, SECRET))),
    ).toThrow(ServiceUnavailableException);
  });
});

import { DocumentService } from './document.service';
import { PrismaService } from 'src/database/prisma.service';

describe('DocumentService.updateDocument', () => {
  let update: jest.Mock;
  let service: DocumentService;

  beforeEach(() => {
    update = jest.fn().mockResolvedValue({ id: 'd1' });
    service = new DocumentService({
      document: { update },
    } as unknown as PrismaService);
  });

  it('advances updatedAt on a real metadata update (rename)', async () => {
    await service.updateDocument({ where: { id: 'd1' }, data: { title: 'New' } });
    const arg = update.mock.calls[0][0] as {
      data: { title?: string; updatedAt?: Date };
    };
    expect(arg.data.title).toBe('New');
    expect(arg.data.updatedAt).toBeInstanceOf(Date);
  });

  it('does not bump updatedAt for an empty / no-op update', async () => {
    // An empty-body PATCH must not re-sort the doc to the top of the list.
    await service.updateDocument({ where: { id: 'd1' }, data: {} });
    const arg = update.mock.calls[0][0] as { data: Record<string, unknown> };
    expect(arg.data).not.toHaveProperty('updatedAt');
    expect(Object.keys(arg.data)).toHaveLength(0);
  });
});

import {
  CanActivate,
  ExecutionContext,
  Injectable,
  Logger,
  ServiceUnavailableException,
  UnauthorizedException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { createHmac, timingSafeEqual } from 'crypto';
import type { Request } from 'express';

/**
 * Verifies Yorkie event-webhook requests. Yorkie signs the request body with
 * `HMAC-SHA256(rawBody, project.SecretKey)` and sends it as
 * `X-Signature-256: sha256=<hex>` (see yorkie `pkg/webhook/client.go`). The
 * signing key is the project's secret key, which this backend already holds
 * as `YORKIE_SECRET_KEY` for the admin service — so no new secret is needed.
 *
 * The raw request bytes are captured by the `verify` hook wired into
 * `bodyParser.json` in `main.ts`; HMAC must run over the exact bytes, not a
 * re-serialized object.
 */
@Injectable()
export class YorkieSignatureGuard implements CanActivate {
  private readonly logger = new Logger(YorkieSignatureGuard.name);
  private readonly secretKey?: string;

  constructor(configService: ConfigService) {
    this.secretKey = configService.get<string>('YORKIE_SECRET_KEY');
  }

  canActivate(context: ExecutionContext): boolean {
    if (!this.secretKey) {
      // Without the shared secret we cannot authenticate the caller; refuse
      // rather than trust an unsigned request to mutate `updatedAt`.
      this.logger.error(
        'YORKIE_SECRET_KEY is not configured; rejecting event webhook',
      );
      throw new ServiceUnavailableException('Webhook verification unavailable');
    }

    const req = context
      .switchToHttp()
      .getRequest<Request & { rawBody?: Buffer }>();

    const header = req.header('x-signature-256');
    const rawBody = req.rawBody;
    if (!header || !rawBody) {
      throw new UnauthorizedException('Missing webhook signature');
    }

    const expected = `sha256=${createHmac('sha256', this.secretKey)
      .update(rawBody)
      .digest('hex')}`;

    const a = Buffer.from(header);
    const b = Buffer.from(expected);
    if (a.length !== b.length || !timingSafeEqual(a, b)) {
      throw new UnauthorizedException('Invalid webhook signature');
    }
    return true;
  }
}

import { Body, Controller, HttpCode, Post, UseGuards } from '@nestjs/common';
import { SkipThrottle } from '@nestjs/throttler';
import { DocumentService } from './document.service';
import { parseYorkieDocKey } from '../yorkie/yorkie-doc-key';
import { YorkieSignatureGuard } from './yorkie-signature.guard';

/**
 * Shape of Yorkie's event-webhook body (yorkie 0.7.12,
 * `api/types/event_webhook.go`). Typed loosely and validated by hand so an
 * unexpected/extra field never turns into a 4xx — Yorkie retries on failure,
 * and we would rather swallow-and-200 anything we don't recognize than
 * trigger a retry storm.
 */
interface YorkieEventBody {
  type?: string;
  attributes?: { key?: string; issuedAt?: string };
}

/** The only webhook event type yorkie emits (fired on real root edits). */
const DOCUMENT_ROOT_CHANGED = 'DocumentRootChanged';

/**
 * Receives Yorkie document event webhooks and mirrors the last-edit time into
 * Postgres (`Document.updatedAt`), which is what the documents list orders by.
 * This is how content edits — which flow client → Yorkie only, never through
 * this backend — become visible to the list without a per-request Yorkie admin
 * call. Authenticated by HMAC signature ({@link YorkieSignatureGuard}); not
 * behind the JWT guard. `@SkipThrottle` so bursts of edit events aren't
 * rate-limited away.
 */
@Controller('internal/yorkie')
@SkipThrottle()
@UseGuards(YorkieSignatureGuard)
export class YorkieEventController {
  constructor(private readonly documentService: DocumentService) {}

  @Post('events')
  @HttpCode(200)
  async handleEvent(@Body() body: YorkieEventBody): Promise<{ ok: true }> {
    if (body?.type !== DOCUMENT_ROOT_CHANGED) {
      return { ok: true };
    }

    const key = body.attributes?.key;
    const parsed = key ? parseYorkieDocKey(key) : null;
    if (!parsed) {
      return { ok: true };
    }

    // Trust Yorkie's issue time as the edit time, but clamp it to now() and
    // fall back to now() if missing/unparseable. `touchUpdatedAt` only moves
    // the time forward, so a clock-skewed *future* issuedAt would otherwise pin
    // updatedAt ahead and make the monotonic guard reject every later real
    // edit until wall-clock caught up. Out-of-order / duplicate deliveries stay
    // harmless.
    const now = Date.now();
    const issuedMs = Date.parse(body.attributes?.issuedAt ?? '');
    const at = new Date(Number.isNaN(issuedMs) ? now : Math.min(issuedMs, now));

    await this.documentService.touchUpdatedAt(parsed.id, at);
    return { ok: true };
  }
}

import { Injectable, Logger, OnModuleDestroy } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { connect, ClientHttp2Session } from 'http2';

/**
 * Projected "currently editing" user. Backend-shaped so the React layer
 * never sees Yorkie's wire format (per-client maps, JSON-stringified
 * values, etc.).
 */
export type PresenceUser = {
  username: string;
  photo?: string;
  email?: string;
};

type RawPresences = {
  [clientId: string]: { data: { [key: string]: string } };
};

type RawDocumentSummary = {
  key: string;
  presences?: RawPresences;
  // RFC3339 timestamp of the last document change. Yorkie's connect-go
  // protojson response emits camelCase (`updatedAt`); the snake_case name is
  // accepted too for resilience across gateway/transcoding configs.
  updatedAt?: string;
  updated_at?: string;
};

type GetDocumentsResponse = {
  documents?: Array<RawDocumentSummary>;
  error?: { message?: string; code?: string };
};

/**
 * Per-document metadata read from Yorkie's admin `GetDocuments`: the live
 * editors and the last-modified time. `updatedAt` is an ISO string, or
 * undefined when Yorkie has no valid timestamp for the document.
 */
export type DocumentSummary = {
  editors: PresenceUser[];
  updatedAt?: string;
};

const REQUEST_TIMEOUT_MS = 800;

/**
 * HTTP/2 client for Yorkie's AdminService. Holds a single long-lived
 * ClientHttp2Session and multiplexes requests on it; the session is
 * lazily re-created on close/error. Failures degrade silently to an
 * empty map — presence is decorative, the listing must still succeed.
 */
@Injectable()
export class YorkieAdminService implements OnModuleDestroy {
  private readonly logger = new Logger(YorkieAdminService.name);
  private readonly apiAddr: string;
  private readonly secretKey?: string;
  private session?: ClientHttp2Session;

  constructor(configService: ConfigService) {
    this.apiAddr =
      configService.get<string>('YORKIE_RPC_ADDR') ?? 'http://localhost:8080';
    this.secretKey = configService.get<string>('YORKIE_SECRET_KEY');
  }

  onModuleDestroy(): void {
    if (this.session && !this.session.destroyed) {
      this.session.close();
      this.session = undefined;
    }
  }

  /**
   * Fetch per-document metadata (live editors + last-modified time) for the
   * given Yorkie document keys. Returns a map keyed by document key;
   * documents Yorkie has never seen (or when no admin key is configured)
   * are absent, letting callers fall back to Postgres data.
   */
  async getSummaries(
    documentKeys: ReadonlyArray<string>,
  ): Promise<Map<string, DocumentSummary>> {
    const out = new Map<string, DocumentSummary>();
    if (documentKeys.length === 0) return out;
    if (!this.secretKey) {
      // No admin key configured — degrade silently. Expected for local
      // environments that haven't provisioned a project secret yet.
      return out;
    }

    try {
      const response = await this.requestGetDocuments(documentKeys);
      for (const doc of response.documents ?? []) {
        out.set(doc.key, projectSummary(doc));
      }
    } catch (err) {
      this.logger.warn(
        `Yorkie admin getSummaries failed: ${(err as Error).message}`,
      );
    }
    return out;
  }

  /**
   * Fetch "currently editing" users for the given Yorkie document keys.
   * Returns a map keyed by document key. Documents with no active clients
   * are absent. Thin projection over {@link getSummaries}.
   */
  async getEditors(
    documentKeys: ReadonlyArray<string>,
  ): Promise<Map<string, PresenceUser[]>> {
    const out = new Map<string, PresenceUser[]>();
    for (const [key, summary] of await this.getSummaries(documentKeys)) {
      if (summary.editors.length > 0) out.set(key, summary.editors);
    }
    return out;
  }

  private getSession(): ClientHttp2Session {
    if (this.session && !this.session.destroyed && !this.session.closed) {
      return this.session;
    }
    const session = connect(this.apiAddr);
    // Detach on any terminal state so the next call lazily reconnects.
    const drop = () => {
      if (this.session === session) this.session = undefined;
    };
    session.once('close', drop);
    session.once('error', (err) => {
      this.logger.warn(`Yorkie admin session error: ${err.message}`);
      drop();
      if (!session.destroyed) session.close();
    });
    // Yorkie admin idle timeouts can otherwise kill the multiplexed session
    // mid-request; allow the session to outlive the event loop while idle.
    session.unref();
    this.session = session;
    return session;
  }

  private requestGetDocuments(
    documentKeys: ReadonlyArray<string>,
  ): Promise<GetDocumentsResponse> {
    return new Promise((resolve, reject) => {
      let session: ClientHttp2Session;
      try {
        session = this.getSession();
      } catch (err) {
        reject(err as Error);
        return;
      }
      // Re-ref while a request is in-flight so a busy session keeps the
      // process alive; unref again on settle.
      session.ref();

      const body = JSON.stringify({
        document_keys: documentKeys,
        include_root: false,
        include_presences: true,
      });

      let settled = false;
      const settle = (fn: () => void) => {
        if (settled) return;
        settled = true;
        clearTimeout(timeout);
        session.unref();
        fn();
      };

      let req;
      try {
        req = session.request({
          ':method': 'POST',
          ':path': '/yorkie.v1.AdminService/GetDocuments',
          'content-type': 'application/json',
          'content-length': Buffer.byteLength(body).toString(),
          authorization: `API-Key ${this.secretKey}`,
        });
      } catch (err) {
        session.unref();
        reject(err as Error);
        return;
      }

      const timeout = setTimeout(() => {
        req.close();
        settle(() => reject(new Error('Yorkie admin request timed out')));
      }, REQUEST_TIMEOUT_MS);

      let status = 0;
      req.on('response', (headers) => {
        status = Number(headers[':status']) || 0;
      });

      let data = '';
      req.setEncoding('utf8');
      req.on('data', (chunk) => {
        data += chunk;
      });
      req.on('end', () => {
        settle(() => {
          if (status >= 400) {
            reject(
              new Error(
                `Yorkie admin returned HTTP ${status}${data ? `: ${data.slice(0, 200)}` : ''}`,
              ),
            );
            return;
          }
          try {
            const parsed = JSON.parse(data) as GetDocumentsResponse;
            if (parsed.error) {
              reject(new Error(parsed.error.message ?? 'Yorkie admin error'));
              return;
            }
            resolve(parsed);
          } catch (err) {
            reject(
              new Error(
                `Failed to parse Yorkie admin response: ${(err as Error).message}`,
              ),
            );
          }
        });
      });
      req.on('error', (err) => {
        settle(() => reject(err));
      });

      req.write(body);
      req.end();
    });
  }
}

/**
 * Strip Yorkie's per-field JSON-stringification (`"\"alice\""` → `"alice"`)
 * and decode-uri-component-safe usernames; bail to undefined for malformed
 * input rather than emitting `"undefined"` text.
 */
function unwrap(value: string | undefined): string | undefined {
  if (value === undefined) return undefined;
  let next: unknown = value;
  try {
    next = JSON.parse(value);
  } catch {
    // Keep raw on parse failure — most fields are strings JSON.stringify'd
    // by the SDK but very early test data could be bare.
  }
  if (typeof next !== 'string') return undefined;
  return next;
}

/**
 * Project a raw Yorkie `GetDocuments` entry into our backend-shaped summary.
 * Reads the last-modified timestamp from camelCase `updatedAt` (protojson's
 * output form), falling back to snake_case for resilience.
 */
export function projectSummary(doc: RawDocumentSummary): DocumentSummary {
  return {
    editors: projectUsers(doc.presences),
    updatedAt: parseTimestamp(doc.updatedAt ?? doc.updated_at),
  };
}

/**
 * Normalize a Yorkie RFC3339 timestamp into an ISO string. Returns
 * undefined for missing, empty, epoch-zero (Yorkie's "unset"), or
 * unparseable values so callers can fall back to Postgres data.
 */
export function parseTimestamp(value: string | undefined): string | undefined {
  if (!value) return undefined;
  const ms = Date.parse(value);
  if (Number.isNaN(ms) || ms <= 0) return undefined;
  return new Date(ms).toISOString();
}

function projectUsers(presences: RawPresences | undefined): PresenceUser[] {
  if (!presences) return [];
  const seen = new Map<string, PresenceUser>();
  for (const [clientId, entry] of Object.entries(presences)) {
    const data = entry?.data ?? {};
    const username = unwrap(data.username) ?? '';
    const email = unwrap(data.email) ?? '';
    const photo = unwrap(data.photo) || undefined;
    if (!username && !email) continue;
    const key = email || username || clientId;
    if (seen.has(key)) continue;
    seen.set(key, {
      username: username || email,
      photo,
      email: email || undefined,
    });
  }
  return Array.from(seen.values());
}

import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import * as bodyParser from 'body-parser';
import * as cookieParser from 'cookie-parser';
import type { IncomingMessage } from 'http';
import { Logger } from 'nestjs-pino';
import { AppModule } from './app.module';

/**
 * JSON body cap. The default Express limit (100kB) is too small for the
 * `PUT /api/v1/.../documents/:id/content` endpoint — the CLI's docx
 * importer emits inline `data:` URLs for embedded images, so a single
 * screenshot easily blows past the default. 25MB matches the practical
 * docx file ceiling and keeps malicious-payload exposure bounded.
 *
 * Override with `BACKEND_JSON_BODY_LIMIT` (e.g., `'50mb'`) when a
 * specific install needs more headroom; the value is passed verbatim to
 * `body-parser`.
 */
const JSON_BODY_LIMIT = process.env.BACKEND_JSON_BODY_LIMIT ?? '25mb';

/**
 * The only route whose raw request bytes must be retained (for the Yorkie
 * event-webhook HMAC check). Must match the controller path in
 * `document/yorkie-event.controller.ts`.
 */
const YORKIE_WEBHOOK_PATH = '/internal/yorkie/events';

async function bootstrap() {
  const app = await NestFactory.create(AppModule, { bufferLogs: true });
  app.useLogger(app.get(Logger));
  // Trust the upstream proxy hop count from BACKEND_TRUST_PROXY so
  // req.ip resolves to the real client IP (rate limiter and audit
  // logging key off this). Defaults to 0 — turning on `trust proxy`
  // without a real proxy in front lets a client spoof X-Forwarded-For
  // and bypass per-IP limits. Set to 1 (typical: nginx, Cloudflare
  // single hop) when deploying behind an edge that strips client XFF.
  const trustProxy = Number(process.env.BACKEND_TRUST_PROXY ?? '0');
  if (Number.isFinite(trustProxy) && trustProxy > 0) {
    app.getHttpAdapter().getInstance().set('trust proxy', trustProxy);
  }
  // Stash the raw request bytes so the Yorkie event-webhook guard can verify
  // its HMAC signature over the exact payload (a re-serialized object would
  // not match). Scoped to the webhook path only: retaining the buffer on every
  // JSON request would roughly double peak memory on the 25MB content-import
  // routes, which never need it.
  app.use(
    bodyParser.json({
      limit: JSON_BODY_LIMIT,
      verify: (req: IncomingMessage & { rawBody?: Buffer }, _res, buf) => {
        if (req.url?.split('?', 1)[0] === YORKIE_WEBHOOK_PATH) {
          req.rawBody = buf;
        }
      },
    }),
  );
  app.use(bodyParser.urlencoded({ limit: JSON_BODY_LIMIT, extended: true }));
  app.use(cookieParser());
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
      transformOptions: { enableImplicitConversion: false },
    }),
  );
  app.enableCors({
    origin: [process.env.FRONTEND_URL],
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  });
  await app.listen(process.env.PORT ?? 3000);
}
bootstrap();

import { INestApplication, ValidationPipe } from '@nestjs/common';
import { PrismaService } from 'src/database/prisma.service';

export const TEST_ENCRYPTION_KEY =
  '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef';
export const DEFAULT_TEST_DATABASE_URL =
  'postgresql://wafflebase:wafflebase@localhost:5432/wafflebase';
export const TEST_JWT_SECRET = 'test-jwt-secret';

const runDbIntegrationTests =
  process.env.RUN_DB_INTEGRATION_TESTS === 'true';
export const describeDb = runDbIntegrationTests ? describe : describe.skip;

export function parseDatabaseUrl(databaseUrl: string) {
  const url = new URL(databaseUrl);
  return {
    host: url.hostname,
    port: Number(url.port || 5432),
    database: url.pathname.replace(/^\//, ''),
    username: decodeURIComponent(url.username),
    password: decodeURIComponent(url.password),
  };
}

export async function clearDatabase(prisma: PrismaService) {
  await prisma.apiKey.deleteMany();
  await prisma.shareLink.deleteMany();
  await prisma.dataSource.deleteMany();
  await prisma.document.deleteMany();
  await prisma.workspaceInvite.deleteMany();
  await prisma.workspaceMember.deleteMany();
  await prisma.workspace.deleteMany();
  await prisma.user.deleteMany();
}

export async function createWorkspace(
  prisma: PrismaService,
  userId: number,
  name = 'test-workspace',
) {
  const slug = `${name}-${Date.now()}`;
  const workspace = await prisma.workspace.create({
    data: { name, slug },
  });
  await prisma.workspaceMember.create({
    data: { workspaceId: workspace.id, userId, role: 'owner' },
  });
  return workspace;
}

export function createUserFactory(prisma: PrismaService, prefix = 'test') {
  let seq = 0;
  return () => {
    seq += 1;
    return prisma.user.create({
      data: {
        authProvider: 'github',
        username: `${prefix}-user-${seq}`,
        email: `${prefix}-user-${seq}@example.com`,
      },
    });
  };
}

export function setIntegrationEnvDefaults() {
  process.env.DATASOURCE_ENCRYPTION_KEY ??= TEST_ENCRYPTION_KEY;
  process.env.DATABASE_URL ??= DEFAULT_TEST_DATABASE_URL;
}

/**
 * Mirrors the production `main.ts` bootstrap pipeline so e2e suites
 * exercise the same validation contract that real traffic hits. If
 * this drifts from `main.ts`, integration coverage starts lying.
 */
export function applyGlobalBootstrap(app: INestApplication) {
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
      transformOptions: { enableImplicitConversion: false },
    }),
  );
}

export function setAuthEnvDefaults() {
  process.env.JWT_SECRET ??= TEST_JWT_SECRET;
  process.env.FRONTEND_URL ??= 'http://localhost:5173';
  process.env.GITHUB_CLIENT_ID ??= 'test-client-id';
  process.env.GITHUB_CLIENT_SECRET ??= 'test-client-secret';
  process.env.GITHUB_CALLBACK_URL ??=
    'http://localhost:3000/auth/github/callback';
}
